import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema registration', () => {
  it('rejects an invalid static schema at registration with the tool name', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Invalid location schema',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });
});

describe('ToolRegistry dynamic schemas', () => {
  // specs/hal-engine-tool-input-validation/spec.md#9
  it('validates each resolved schema and compiles each schema object once', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      const registry = new ToolRegistry();
      const locationSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
      const unitsSchema = {type: 'object', properties: {units: {type: 'string'}}, required: ['units']};
      let currentSchema: Record<string, unknown> = locationSchema;
      const executor = jest.fn(async () => 'ok');
      registry.register(() => ({name: 'weather', description: 'Weather', inputSchema: currentSchema}), executor);

      await registry.execute('weather', {location: 'Paris'});
      await registry.execute('weather', {location: 'Berlin'});
      currentSchema = unitsSchema;
      const rejected = await registry.execute('weather', {location: 'Paris'});

      expect(rejected.result).toMatch(/units.*required|required.*units/i);
      expect(executor).toHaveBeenCalledTimes(2);
      expect(compile).toHaveBeenCalledTimes(2);
    } finally {
      compile.mockRestore();
    }
  });
});

describe('ToolRegistry static schemas', () => {
  // specs/hal-engine-tool-input-validation/spec.md#8
  it('keeps using the schema compiled at registration', async () => {
    const registry = new ToolRegistry();
    const definition = {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    };
    const executor = jest.fn(async () => 'ok');
    registry.register(definition, executor);

    definition.inputSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['units']};
    const response = await registry.execute('weather', {location: 'Paris'});

    expect(response).toEqual({result: 'ok'});
    expect(executor).toHaveBeenCalledTimes(1);
  });
});

describe('ToolRegistry input rejection', () => {
  // specs/hal-engine-tool-input-validation/spec.md#3
  it('names the full path of a nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'object', properties: {city: {type: 'string'}}, required: ['city']}},
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('weather', {location: {}});

    expect(response.result).toMatch(/location[/.]city.*required/);
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required, including its full path when nested, and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16), [names the full path of a nested required property](../../src/orchestration/tools/registry.test.ts#L70)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94), [rejects an invalid static schema at registration with the tool name](../../src/orchestration/tools/registry.test.ts#L6)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: keeps using the schema compiled at registration](../../src/orchestration/tools/registry.test.ts#L50)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates each resolved schema and compiles each schema object once](../../src/orchestration/tools/registry.test.ts#L24)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
